/**
 * Background music + the intro score.
 *
 * Two <audio> elements (Vite asset URLs, same origin, so the CSP's `media-src 'self'` covers them) that crossfade into
 * each other. Browsers only allow sound after a user gesture, so everything is queued until `unlock()` (App installs a
 * one-time pointerdown / keydown listener). Settings live in memory only: nothing is stored.
 *
 * Music is original, generated by scripts/music/compose.py.
 */
import { useSyncExternalStore } from 'react';
import goldenHourUrl from '../assets/audio/golden-hour.m4a';
import nightDriveUrl from '../assets/audio/night-drive.m4a';
import sundayPopUrl from '../assets/audio/sunday-pop.m4a';
import introScoreUrl from '../assets/audio/intro.m4a';

// The single-file preview inlines audio as data: URLs, which a strict media-src can refuse; blob: is allowed.
function playable(url: string): string {
  if (!url.startsWith('data:')) return url;
  const [head, body] = url.split(',', 2);
  const bin = atob(body);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return URL.createObjectURL(new Blob([bytes], { type: head.slice(5).split(';')[0] || 'audio/mp4' }));
}
const goldenHour = playable(goldenHourUrl);
const nightDrive = playable(nightDriveUrl);
const sundayPop = playable(sundayPopUrl);
const introScore = playable(introScoreUrl);

export type TrackId = string;
export interface AudioState {
  enabled: boolean;
  volume: number; // 0..1
  track: TrackId;
  unlocked: boolean;
  mode: 'off' | 'intro' | 'background';
  /** true while sound is actually coming out (unlocked, enabled, element playing, tab visible) */
  playing: boolean;
}
export interface TrackMeta {
  id: TrackId;
  name: string;
  /** a two-word mood line for the picker */
  vibe?: string;
}

export const TRACKS: TrackMeta[] = [
  { id: 'golden-hour', name: 'Golden Hour', vibe: 'Lo-fi chill' },
  { id: 'night-drive', name: 'Night Drive', vibe: 'Synthwave' },
  { id: 'sunday-pop', name: 'Sunday Pop', vibe: 'Indie pop' },
];
const SRC: Record<string, string> = { 'golden-hour': goldenHour, 'night-drive': nightDrive, 'sunday-pop': sundayPop };

/** the intro score: one scene every 7.5 s, then it holds on the last scene and fades out by 40 s */
export const INTRO_SCENE_S = 7.5;
const FADE = 1.2;
const SEEK_FADE = 0.14;

let state: AudioState = { enabled: true, volume: 0.5, track: TRACKS[0].id, unlocked: false, mode: 'off', playing: false };
const subs = new Set<() => void>();
const set = (patch: Partial<AudioState>) => {
  const next = { ...state, ...patch };
  if ((Object.keys(patch) as (keyof AudioState)[]).every((k) => next[k] === state[k])) return;
  state = next;
  subs.forEach((fn) => fn());
};

// ------------------------------------------------------------------------------------------------ elements
interface Deck {
  el: HTMLAudioElement;
  /** crossfade gain 0..1 (multiplied with the user volume) */
  gain: number;
  raf: number;
  timer: number;
}
const can = typeof window !== 'undefined' && typeof Audio !== 'undefined';
let decks: [Deck, Deck] | null = null;
let live = 0; // index of the deck that is (or will be) audible
/** where the intro reel is, so a late first tap starts the score in sync */
let introAnchor = { scene: 0, at: 0 };

function getDecks(): [Deck, Deck] | null {
  if (!can) return null;
  if (!decks) {
    const make = (): Deck => {
      const el = new Audio();
      el.preload = 'auto';
      el.addEventListener('playing', sync);
      el.addEventListener('pause', sync);
      el.addEventListener('ended', sync);
      return { el, gain: 0, raf: 0, timer: 0 };
    };
    decks = [make(), make()];
  }
  return decks;
}

const hidden = () => typeof document !== 'undefined' && document.visibilityState === 'hidden';
const apply = (d: Deck) => {
  try {
    d.el.volume = Math.max(0, Math.min(1, d.gain * state.volume));
  } catch {
    /* some browsers make volume read-only (iOS): on/off still works through pause */
  }
};
function sync() {
  const ds = decks;
  set({ playing: !!ds && ds.some((d) => !d.el.paused && d.gain > 0.001) && state.enabled && !hidden() });
}

function play(d: Deck) {
  try {
    const p = d.el.play();
    if (p && typeof p.catch === 'function')
      p.catch((e: unknown) => {
        // NotAllowedError: the gesture did not count; wait for the next one. Anything else (decode/abort) is ignored.
        if (e && (e as { name?: string }).name === 'NotAllowedError') set({ unlocked: false });
        sync();
      });
  } catch {
    /* never throw from the audio layer */
  }
}
function pause(el: HTMLAudioElement) {
  try {
    el.pause();
  } catch {
    /* ignore */
  }
}

/** ramp a deck's gain to `to` over `secs`, then call `done` */
function stopRamp(d: Deck) {
  cancelAnimationFrame(d.raf);
  clearTimeout(d.timer);
}
function rampTo(d: Deck, to: number, secs: number, done?: () => void) {
  stopRamp(d);
  const from = d.gain;
  const t0 = performance.now();
  const step = () => {
    const k = secs <= 0 ? 1 : Math.min(1, (performance.now() - t0) / (secs * 1000));
    // equal-power-ish curve: smooth start and end
    d.gain = from + (to - from) * (k * k * (3 - 2 * k));
    apply(d);
    if (k < 1) {
      if (hidden()) d.timer = window.setTimeout(step, 50);
      else d.raf = requestAnimationFrame(step);
    } else {
      done?.();
      sync();
    }
  };
  step();
}

const same = (el: HTMLAudioElement, src: string) => !!el.getAttribute('src') && el.getAttribute('src') === src;

/** crossfade to `src` starting at `at` seconds (null: carry on from where this source was paused) */
function crossTo(src: string, at: number | null, loop: boolean, fade = FADE) {
  const ds = getDecks();
  if (!ds) return;
  const cur = ds[live];
  // same source on the live deck: keep it going, or resume it where it was (music back on, tab visible again)
  if (same(cur.el, src) && !cur.el.ended && (at === null || !cur.el.paused)) {
    cur.el.loop = loop;
    if (cur.el.paused) play(cur);
    rampTo(cur, 1, fade);
    return;
  }
  const nextIdx = live ^ 1;
  const next = ds[nextIdx];
  rampTo(cur, 0, fade, () => pause(cur.el));
  stopRamp(next);
  if (!same(next.el, src)) next.el.src = src;
  next.el.loop = loop;
  next.gain = 0;
  apply(next);
  try {
    next.el.currentTime = at ?? 0;
  } catch {
    /* not seekable yet: starts at 0 */
  }
  live = nextIdx;
  play(next);
  rampTo(next, 1, fade);
}

function fadeAllOut(secs = 0.5) {
  const ds = decks;
  if (!ds) return;
  ds.forEach((d) => rampTo(d, 0, secs, () => pause(d.el)));
}

/** start (or resume) whatever the current mode asks for */
function start() {
  if (!state.unlocked || !state.enabled || hidden()) return;
  if (state.mode === 'intro') {
    const elapsed = introAnchor.at ? (performance.now() - introAnchor.at) / 1000 : 0;
    const max = introAnchor.scene >= 4 ? 40 : INTRO_SCENE_S - 0.2;
    crossTo(introScore, introAnchor.scene * INTRO_SCENE_S + Math.min(max, elapsed), false, 0.35);
  } else if (state.mode === 'background') {
    crossTo(SRC[state.track] ?? SRC[TRACKS[0].id], null, true);
  }
}

// ------------------------------------------------------------------------------------------- visibility
let wasPlaying = false;
if (typeof document !== 'undefined') {
  document.addEventListener('visibilitychange', () => {
    const ds = decks;
    if (!ds) return;
    const d = ds[live];
    if (hidden()) {
      wasPlaying = !d.el.paused;
      ds.forEach((x) => pause(x.el));
      // a crossfade in progress: settle it so the right deck resumes
      ds.forEach(stopRamp);
      ds[live ^ 1].gain = 0;
      d.gain = 1;
      ds.forEach(apply);
    } else if (wasPlaying && state.enabled && state.unlocked && state.mode !== 'off') {
      wasPlaying = false;
      play(d);
    }
    sync();
  });
}

// --------------------------------------------------------------------------------------------- the API
export const audio = {
  getState: (): AudioState => state,
  subscribe: (fn: () => void) => {
    subs.add(fn);
    return () => void subs.delete(fn);
  },
  /** call from any pointerdown / keydown: starts whatever is queued */
  unlock: () => {
    if (state.unlocked || !can) return;
    set({ unlocked: true });
    if (state.mode === 'off') set({ mode: 'background' });
    start();
  },
  /** the tutorial score, synced to the intro scenes (scene index 0..n-1); queued until unlock */
  playIntro: () => {
    introAnchor = { scene: 0, at: performance.now() };
    set({ mode: 'intro' });
    // warm the file so the first tap starts it immediately
    const ds = getDecks();
    if (ds && !state.unlocked) {
      const d = ds[live ^ 1];
      if (!same(d.el, introScore)) d.el.src = introScore;
    }
    start();
  },
  /** jump the score to scene i (short fade); a no-op when the score is already there */
  introScene: (index: number) => {
    const i = Math.max(0, Math.floor(index));
    introAnchor = { scene: i, at: performance.now() };
    if (state.mode !== 'intro' || !state.unlocked || !state.enabled) return;
    const ds = decks;
    if (!ds) return;
    const d = ds[live];
    const target = i * INTRO_SCENE_S;
    if (!same(d.el, introScore) || d.el.paused) {
      start();
      return;
    }
    if (Math.abs(d.el.currentTime - target) < 0.35) return;
    rampTo(d, 0, SEEK_FADE, () => {
      try {
        d.el.currentTime = target;
      } catch {
        /* ignore */
      }
      if (d.el.ended || d.el.paused) play(d);
      rampTo(d, 1, SEEK_FADE * 1.5);
    });
  },
  /** leave the intro: crossfade into the background track */
  stopIntro: () => {
    if (state.mode === 'background') return;
    set({ mode: 'background' });
    start();
  },
  playBackground: () => {
    set({ mode: 'background' });
    start();
  },
  setEnabled: (on: boolean) => {
    if (on === state.enabled) return;
    set({ enabled: on });
    if (on) {
      if (state.mode === 'off') set({ mode: 'background' });
      // turning music on is itself a gesture
      if (!state.unlocked && can) set({ unlocked: true });
      start();
    } else {
      fadeAllOut(0.45);
    }
    sync();
  },
  setVolume: (v: number) => {
    const vol = Math.max(0, Math.min(1, Number.isFinite(v) ? v : 0.5));
    set({ volume: vol });
    decks?.forEach(apply);
  },
  setTrack: (id: TrackId) => {
    if (!SRC[id]) return;
    set({ track: id });
    if (state.mode === 'background' || state.mode === 'off') {
      set({ mode: 'background' });
      if (!state.enabled) return;
      if (!state.unlocked && can) set({ unlocked: true });
      start();
    }
  },
};

/** React binding: re-renders on any audio state change */
export function useAudio(): AudioState {
  return useSyncExternalStore(audio.subscribe, audio.getState, audio.getState);
}

/** debug / test hook: the two decks (read-only) */
export function _decks(): readonly HTMLAudioElement[] {
  return decks ? decks.map((d) => d.el) : [];
}
